@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/exampleWebAPI_354btrh> ;
            sh:resultMessage "at least one action must be provided for a webAPI distribution" ;
            sh:resultPath schema1:potentialAction ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "at least one action must be provided for a webAPI distribution" ;
                    sh:minCount 1 ;
                    sh:or ( [ sh:class schema1:Action ] [ sh:class schema1:AssessAction ] [ sh:class schema1:ConsumeAction ] [ sh:class schema1:ControlAction ] [ sh:class schema1:CreateAction ] [ sh:class schema1:DeleteAction ] [ sh:class schema1:FindAction ] [ sh:class schema1:InteractAction ] [ sh:class schema1:MoveAction ] [ sh:class schema1:PlayAction ] [ sh:class schema1:SearchAction ] [ sh:class schema1:TransferAction ] [ sh:class schema1:UpdateAction ] ) ;
                    sh:path schema1:potentialAction ] ] .

